','Y',1,'0','超过该时长未处理标记为临近/超时',NULL,'0',NULL,1,'2026-09-18 10:47:55',NULL,NULL),(1012,'cmd.approval.sla.warn.ratio','审批-SLA预警比例','0.8','NUMBER','WORKFLOW','0.8','Y','Y',2,'0','已消耗时长占比超过该值视为临近超时',NULL,'0',NULL,1,'2026-09-18 10:47:55',NULL,NULL),(1013,'cmd.approval.escalate.enabled','审批-超时自动升级GC','true','BOOLEAN','WORKFLOW','true','N','Y',3,'0','开启后超 SLA 自动升级至 GC Scope',NULL,'0',NULL,1,'2026-09-18 10:47:55',NULL,NULL),(1014,'cmd.import.max.rows','导入-单批次最大行数','50000','NUMBER','IMPORT','50000','N','Y',1,'0','超过该行数需拆分批次',NULL,'0',NULL,1,'2026-09-18 10:47:55',NULL,NULL),(1015,'cmd.import.default.error.strategy','导入-默认错误策略','REJECT_ROW','STRING','IMPORT','REJECT_ROW','N','Y',2,'0','REJECT_ROW 跳过错误行 / ABORT_ALL 全部回滚',NULL,'0',NULL,1,'2026-09-18 10:47:55',NULL,NULL),(1016,'cmd.import.default.dup.strategy','导入-默认重复策略','GOVERNANCE','STRING','IMPORT','GOVERNANCE','N','Y',3,'0','GOVERNANCE 转治理 / SKIP 跳过 / OVERWRITE 覆盖',NULL,'0',NULL,1,'2026-09-18 10:47:55',NULL,NULL),(1017,'cmd.integration.max.retry','集成-默认最大重试次数','3','NUMBER','INTEGRATION','3','N','Y',1,'0','单次运行最多重试次数',NULL,'0',NULL,1,'2026-09-18 10:47:55',NULL,NULL),(1018,'cmd.audit.retention.days','审计-日志保留天数','730','NUMBER','AUDIT','730','N','Y',1,'0','审计事件保留天数（POC 保留 2 年）',NULL,'0',NULL,1,'2026-09-18 10:47:55',NULL,NULL),(1019,'cmd.hierarchy.loop_check.enabled','层级-启用环路检测','true','BOOLEAN','HIERARCHY','true','Y','Y',1,'0','层级关系提交前强制检测父子相同/多父冲突/路径循环',NULL,'0',NULL,1,'2026-09-18 10:47:55',NULL,NULL),(1020,'cmd.ui.page.size','界面-默认分页大小','20','NUMBER','UI','20','N','Y',1,'0','列表页默认每页条数',NULL,'0',NULL,1,'2026-09-18 10:47:55',NULL,NULL);
