mn:userTask>\n\n    <bpmn:exclusiveGateway id=\"Gateway_2\" name=\"是否驳回\" default=\"f_gc_approve\">\n      <bpmn:incoming>f_gc_gw</bpmn:incoming>\n      <bpmn:outgoing>f_gc_reject</bpmn:outgoing>\n      <bpmn:outgoing>f_gc_approve</bpmn:outgoing>\n    </bpmn:exclusiveGateway>\n\n    <bpmn:endEvent id=\"EndEvent_Approve\" name=\"审批通过\">\n      <bpmn:incoming>f_bu_approve</bpmn:incoming>\n      <bpmn:incoming>f_gc_approve</bpmn:incoming>\n    </bpmn:endEvent>\n\n    <bpmn:endEvent id=\"EndEvent_Reject\" name=\"审批驳回\">\n      <bpmn:incoming>f_bu_reject</bpmn:incoming>\n      <bpmn:incoming>f_gc_reject</bpmn:incoming>\n    </bpmn:endEvent>\n\n    <bpmn:sequenceFlow id=\"f_start_apply\" sourceRef=\"StartEvent_1\" targetRef=\"Activity_Apply\"/>\n    <bpmn:sequenceFlow id=\"f_apply_bu\" sourceRef=\"Activity_Apply\" targetRef=\"Activity_BUReview\"/>\n    <bpmn:sequenceFlow id=\"f_bu_gw\" sourceRef=\"Activity_BUReview\" targetRef=\"Gateway_1\"/>\n    <bpmn:sequenceFlow id=\"f_bu_reject\" name=\"驳回\" sourceRef=\"Gateway_1\" targetRef=\"EndEvent_Reject\">\n      <bpmn:conditionExpression xsi:type=\"bpmn:tFormalExpression\">rejected == True</bpmn:conditionExpression>\n    </bpmn:sequenceFlow>\n    <bpmn:sequenceFlow id=\"f_bu_gc\" name=\"跨BU升级\" sourceRef=\"Gateway_1\" targetRef=\"Activity_GCReview\">\n      <bpmn:conditionExpression xsi:type=\"bpmn:tFormalExpression\">crossBu == True</bpmn:conditionExpression>\n    </bpmn:sequenceFlow>\n    <bpmn:sequenceFlow id=\"f_bu_approve\" name=\"直接批准\" sourceRef=\"Gateway_1\" targetRef=\"EndEvent_Approve\"/>\n    <bpmn:sequenceFlow id=\"f_gc_gw\" sourceRef=\"Activity_GCReview\" targetRef=\"Gateway_2\"/>\n    <bpmn:sequenceFlow id=\"f_gc_reject\" name=\"驳回\" sourceRef=\"Gateway_2\" targetRef=\"EndEvent_Reject\">\n      <bpmn:conditionExpression xsi:type=\"bpmn:tFormalExpression\">rejected == True</bpmn:conditionExpression>\n    </bpmn:sequenceFlow>\n    <bpmn:sequenceFlow id=\"f_gc_approve\" name=\"决策完成\" sourceRef=\"Gateway_2\" targetRe